insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"MARGIN_GTE_7","title":"¿La diferencia llegará a 7 o más?","description":"Se corrige con el marcador final.","category":"abierto","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"margin_gte","n":7},"priority":0,"cooldown":2,"tags":["abierto"]},{"code":"MARGIN_GTE_8","title":"¿Habrá una ventaja de 8 o más carreras?","description":"Se corrige con el marcador final.","category":"abierto","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"margin_gte","n":8},"priority":0,"cooldown":2,"tags":["abierto"]},{"code":"MARGIN_LTE_2","title":"¿La diferencia final será de 2 o menos?","description":"Se corrige con el marcador final.","category":"cerrado","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"margin_lte","n":2},"priority":0,"cooldown":2,"tags":["cerrado"]},{"code":"MARGIN_LTE_3","title":"¿La ventaja final será de 3 o menos?","description":"Se corrige con el marcador final.","category":"cerrado","difficulty":"easy","points":2,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"margin_lte","n":3},"priority":0,"cooldown":2,"tags":["cerrado"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;